window.QUIZ = (window.QUIZ || []).concat([
  { id: "8-001", ch: 8, sec: "8.1", page: 147, type: "concept", level: 1,
    q: "Why does pressure distribution along an irrigation pipe matter for the field, not just for the pump?",
    opts: ["Pressure decides the crop's salt tolerance", "Pressure controls the discharge from sprinklers, gates, and emitters, and so the uniformity and efficiency of application", "Pressure only affects how loud the pipeline is", "Pressure changes the volumetric flow rate in a pipe with one inlet and one outlet"], a: 1,
    why: "Outlets discharge according to pressure, so uneven pressure means uneven water. In a pipe with one inlet and one outlet, continuity keeps Q the same regardless of pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-002", ch: 8, sec: "8.1", page: 147, type: "concept", level: 1,
    q: "Why does the book stress careful hydraulic planning before installing an irrigation system?",
    opts: ["Hydraulic rules change every few years", "Pumps cannot be replaced once installed", "Design and installation mistakes are expensive to correct, while planning to avoid them costs little", "Pipelines never lose pressure if planned"], a: 2,
    why: "The introduction notes that mistakes in sizing pipes, valves, emitters, and pumps are often very expensive to fix, while the cost of good planning is small.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-003", ch: 8, sec: "8.2", page: 147, type: "recall", level: 1,
    q: "Which two physical laws does the book apply to irrigation hydraulics?",
    opts: ["Conservation of momentum and Darcy's law", "Newton's law of cooling and Bernoulli's law of drag", "Conservation of charge and conservation of energy", "Conservation of energy and conservation of mass (continuity)"], a: 3,
    why: "Energy conservation gives the Bernoulli equation, and mass conservation gives continuity, Q = Vm × Af.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-004", ch: 8, sec: "8.2", page: 147, type: "recall", level: 1,
    q: "What are the three forms of energy in water in an irrigation system?",
    opts: ["Velocity (kinetic), elevation (potential), and pressure (potential)", "Velocity, temperature, and pressure", "Friction, elevation, and minor loss", "Elevation, viscosity, and pressure"], a: 0,
    why: "Kinetic energy from motion, potential energy from elevation above a reference, and potential energy from pressure. Friction and minor losses are ways energy is lost, not forms of it.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-005", ch: 8, sec: "8.2", page: 147, type: "recall", level: 2,
    q: "When energy is expressed per unit weight of water, what is it called and what are its dimensions?",
    opts: ["Pressure, with dimensions of force per area", "Power, with dimensions of force times length per time", "Head, with dimensions of length", "Work, with dimensions of force times length"], a: 2,
    why: "Energy (F × L) divided by weight (F) leaves length, so head is in feet. Energy per unit volume gives F/L², which is pressure in psi.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-006", ch: 8, sec: "8.2", page: 147, type: "recall", level: 1,
    q: "What maximum average velocity does the book generally recommend in a pressurized pipeline?",
    opts: ["2 ft/s", "10 ft/s", "15 ft/s", "5 ft/s"], a: 3,
    why: "Above 5 ft/s, sudden flow stoppage can cause damaging pressure surges (water hammer). Higher velocities are acceptable only with protection such as relief valves or surge tanks.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-007", ch: 8, sec: "8.2", page: 147, type: "concept", level: 2,
    q: "What causes water hammer in a pipeline?",
    opts: ["Flow stopped too quickly while upstream water carries a large momentum, creating an impulsive pressure surge", "Air trapped at high points being slowly released", "Friction loss heating the water", "Pumping at too low a flow rate"], a: 0,
    why: "Rapid change of momentum produces an impulsive force. Higher velocity means more momentum, which is why velocity is limited to about 5 ft/s.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-008", ch: 8, sec: "8.2", page: 148, type: "recall", level: 1,
    q: "For water, how many psi correspond to 1 ft of pressure head?",
    opts: ["2.31 psi", "0.433 psi", "62.4 psi", "0.0624 psi"], a: 1,
    why: "From P = γh with γ = 62.4 lb/ft³: 62.4/144 = 0.433 psi per ft. Conversely 1 psi = 2.31 ft of water.",
    eq: "8.3", calc: "eq-8.2-8.3", fig: null, table: null },
  { id: "8-009", ch: 8, sec: "8.2", page: 148, type: "recall", level: 1,
    q: "What specific weight of water does the book use?",
    opts: ["8.33 lb/ft³", "62.4 lb/ft³", "32.2 lb/ft³", "1.0 lb/ft³"], a: 1,
    why: "γ = 62.4 lb/ft³. 8.33 is pounds per gallon, and 32.2 ft/s² is the gravitational constant.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-010", ch: 8, sec: "8.2", page: 148, type: "calc", level: 1,
    q: "What is the pressure at the bottom of a water column 50 ft tall?",
    opts: ["115.5 psi", "50.0 psi", "3,120 psi", "21.7 psi"], a: 3,
    why: "P = 0.433 psi/ft × 50 ft = 21.65 psi, about 21.7 psi. 115.5 multiplies by 2.31 instead, and 3,120 uses 62.4 without converting square feet to square inches.",
    eq: "8.2", calc: "eq-8.2-8.3", fig: null, table: null },
  { id: "8-011", ch: 8, sec: "8.2", page: 148, type: "calc", level: 1,
    q: "A gauge reads 45 psi. What is the equivalent pressure head of water?",
    opts: ["19.5 ft", "45 ft", "104 ft", "2,808 ft"], a: 2,
    why: "h = 2.31 ft/psi × 45 psi = 103.95 ft, about 104 ft. 19.5 multiplies by 0.433 instead.",
    eq: "8.2", calc: "eq-8.2-8.3", fig: null, table: null },
  { id: "8-012", ch: 8, sec: "8.2", page: 148, type: "concept", level: 2,
    q: "Two water columns are both 10 ft tall. One has a cross-section of 1 in², the other 10 in². How do the pressures at their bottoms compare?",
    opts: ["Both are 4.33 psi, although the force on the larger bottom is 10 times greater", "The larger column has 10 times the pressure", "The smaller column has 10 times the pressure", "Both are 23.1 psi"], a: 0,
    why: "Pressure depends only on depth: P = 0.433 × 10 = 4.33 psi. Force = pressure × area, so the 10 in² bottom carries 10 times the force. 23.1 uses 2.31 instead of 0.433.",
    eq: "8.2", calc: "eq-8.2-8.3", fig: "8.1", table: null },
  { id: "8-013", ch: 8, sec: "8.2", page: 148, type: "concept", level: 2,
    q: "Why does the 0.433 psi/ft conversion in Eq. 8.3 not apply to all fluids?",
    opts: ["It is valid only at elevations below 5,000 ft", "It depends on the specific weight of water, and other fluids have different weights per unit volume", "It applies only to flowing water, not still water", "It assumes a pipe diameter of 1 inch"], a: 1,
    why: "P = γh. The 0.433 factor is 62.4/144 for water only. A fertilizer solution or fuel with different γ gives a different factor.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-014", ch: 8, sec: "8.2", page: 147, type: "calc", level: 1,
    q: "Water flows at an average velocity of 6 ft/s in a pipe. What is the velocity head?",
    opts: ["0.19 ft", "1.12 ft", "0.56 ft", "0.09 ft"], a: 2,
    why: "Eq. 8.1: hv = V²/2g = 36/64.4 = 0.56 ft. 1.12 divides by g instead of 2g, and 0.19 uses V instead of V² (6/32.2).",
    eq: "8.1", calc: "eq-8.1", fig: null, table: null },
  { id: "8-015", ch: 8, sec: "8.2", page: 149, type: "calc", level: 2,
    q: "500 gpm flows in a pipe with a 6-in inside diameter. What is the average velocity?",
    opts: ["1.4 ft/s", "22.7 ft/s", "0.47 ft/s", "5.7 ft/s"], a: 3,
    why: "Q = 500/449 = 1.11 cfs. A = π(0.5 ft)²/4 = 0.196 ft². V = 1.11/0.196 = 5.7 ft/s. 22.7 uses the radius as if it were the diameter in A = πd²/4 (area 4 times too small), and 1.4 uses the area of the full 6 in as a radius.",
    eq: "8.5", calc: "eq-8.5", fig: null, table: null },
  { id: "8-016", ch: 8, sec: "8.2", page: 149, type: "recall", level: 2,
    q: "What is hydraulic head?",
    opts: ["The sum of elevation head and pressure head", "The sum of velocity head and pressure head", "The pressure head alone", "Total head minus friction loss"], a: 0,
    why: "Hydraulic head = Z + h. Total head adds velocity head, H = V²/2g + Z + h (Eq. 8.4).",
    eq: "8.4", calc: null, fig: null, table: null },
  { id: "8-017", ch: 8, sec: "8.2", page: 150, type: "calc", level: 3,
    q: "At a point 20 ft above the reference, a pipe with a 6-in inside diameter carries 600 gpm at 50 psi. What is the total head?",
    opts: ["135 ft", "71 ft", "136 ft", "116 ft"], a: 2,
    why: "h = 2.31 × 50 = 115.5 ft. V = 1.337 cfs / 0.196 ft² = 6.8 ft/s, hv = 6.8²/64.4 = 0.72 ft. H = 20 + 115.5 + 0.72 = 136.2 ft. 135 ft drops the velocity head, 71 adds psi to feet, and 116 forgets elevation.",
    eq: "8.4", calc: "eq-8.4", fig: null, table: null },
  { id: "8-018", ch: 8, sec: "8.2", page: 150, type: "concept", level: 3,
    q: "The same flow passes from a 4-in pipe into a 10-in pipe. By what factor does the velocity head change?",
    opts: ["It drops to about 0.026 times the 4-in value", "It drops to 0.4 times the 4-in value", "It drops to 0.16 times the 4-in value", "It stays the same because Q is the same"], a: 0,
    why: "V scales with 1/d², so hv = V²/2g scales with 1/d⁴: (4/10)⁴ = 0.0256. 0.4 is the diameter ratio and 0.16 its square, which is the velocity ratio.",
    eq: "8.1", calc: null, fig: null, table: null },
  { id: "8-019", ch: 8, sec: "8.2", page: 149, type: "concept", level: 1,
    q: "By continuity, what happens to velocity when the same flow moves from a larger pipe into a smaller pipe?",
    opts: ["Velocity decreases in proportion to the area", "Velocity stays the same and the flow rate drops", "Velocity stays the same and the pressure doubles", "Velocity increases in inverse proportion to the flow area"], a: 3,
    why: "Q = Vm × Af is the same at every point in a single pipe system, so a smaller area forces a higher velocity.",
    eq: "8.5", calc: null, fig: null, table: null },
  { id: "8-020", ch: 8, sec: "8.2", page: 149, type: "recall", level: 2,
    q: "In the Bernoulli equation H1 = H2 + hL, what does hL represent?",
    opts: ["Head gained from the pump between the points", "Head lost to friction and minor losses between point 1 and point 2", "The velocity head at point 2", "The elevation difference between the points"], a: 1,
    why: "Eq. 8.6 to 8.8: hL = hf + hm, friction along the pipe plus minor losses in fittings and valves.",
    eq: "8.6", calc: "eq-8.6-8.7", fig: null, table: null },
  { id: "8-021", ch: 8, sec: "8.2", page: 149, type: "calc", level: 1,
    q: "A pipeline has 12 ft of friction head loss and 3 ft of minor head loss. What is the total pressure loss?",
    opts: ["6.5 psi", "34.7 psi", "15.0 psi", "5.2 psi"], a: 0,
    why: "hL = 12 + 3 = 15 ft (Eq. 8.8). Eq. 8.9 in pressure terms: PL = 0.433 × 15 = 6.5 psi. 34.7 multiplies by 2.31, and 5.2 counts only friction.",
    eq: "8.9", calc: "eq-8.8-8.9", fig: null, table: null },
  { id: "8-022", ch: 8, sec: "8.2", page: 150, type: "concept", level: 2,
    q: "When can the velocity head be ignored and the pressure form of Bernoulli (Eq. 8.10) be used?",
    opts: ["Only when the pipe is perfectly level", "Only when the flow is above 5 ft/s", "In most sprinkler and microirrigation systems, where velocity head is a minor part of total head", "Never, velocity head is always the largest component"], a: 2,
    why: "Example 8.2 shows velocity head of 1.6 ft against 139 ft of pressure head. In pressurized systems the change in velocity head between points is insignificant.",
    eq: "8.10", calc: null, fig: null, table: null },
  { id: "8-023", ch: 8, sec: "8.2", page: 151, type: "calc", level: 1,
    q: "A level pipeline has an inlet pressure of 60 psi, 4 psi of friction loss, and 1 psi of minor loss. What is the outlet pressure?",
    opts: ["65 psi", "56 psi", "59 psi", "55 psi"], a: 3,
    why: "Level pipe: P2 = P1 − Pf − Pm = 60 − 4 − 1 = 55 psi. 56 ignores the minor loss.",
    eq: "8.10", calc: "eq-8.10", fig: null, table: null },
  { id: "8-024", ch: 8, sec: "8.2", page: 151, type: "calc", level: 2,
    q: "A pipeline rises 20 ft from inlet to outlet. Inlet pressure is 50 psi and friction loss is 3 psi. What is the outlet pressure?",
    opts: ["55.7 psi", "38.3 psi", "47.0 psi", "0.8 psi"], a: 1,
    why: "P2 = P1 − Pf − 0.433 × Rise = 50 − 3 − 8.66 = 38.3 psi. 55.7 adds the elevation term as if it were a fall, 47.0 forgets the rise, and 0.8 uses 2.31 × 20 as psi.",
    eq: "8.10", calc: "eq-8.10", fig: null, table: null },
  { id: "8-025", ch: 8, sec: "8.2", page: 151, type: "calc", level: 2,
    q: "A pipeline falls 40 ft from inlet to outlet. Inlet pressure is 30 psi and friction loss is 2.5 psi. What is the outlet pressure?",
    opts: ["44.8 psi", "10.2 psi", "27.5 psi", "119.9 psi"], a: 0,
    why: "P2 = 30 − 2.5 + 0.433 × 40 = 27.5 + 17.3 = 44.8 psi. A fall adds pressure. 10.2 treats the fall as a rise, and 119.9 uses 2.31 × 40.",
    eq: "8.10", calc: "eq-8.10", fig: null, table: null },
  { id: "8-026", ch: 8, sec: "8.2", page: 151, type: "calc", level: 3,
    q: "Sprinklers at the end of a lateral need 40 psi. The lateral rises 30 ft and loses 5 psi to friction. What pressure is needed at the inlet?",
    opts: ["48.0 psi", "22.0 psi", "114.3 psi", "58.0 psi"], a: 3,
    why: "P1 = P2 + Pf + 0.433 × Rise = 40 + 5 + 13.0 = 58.0 psi. 22.0 subtracts the rise and friction, and 114.3 uses 2.31 × 30 as psi.",
    eq: "8.10", calc: "eq-8.10", fig: null, table: null },
  { id: "8-027", ch: 8, sec: "8.2", page: 151, type: "figure", level: 1,
    q: "Per Figure 8.4, which expression gives P2 for a pipeline with a fall when P1 is known?",
    opts: ["P2 = P1 − Pf − Pm − 0.433 × Fall", "P2 = P1 + Pf + Pm − 0.433 × Fall", "P2 = P1 − Pf − Pm + 0.433 × Fall", "P2 = P1 − Pf + Pm + 2.31 × Fall"], a: 2,
    why: "Going downhill converts elevation into pressure, so the fall term is added while friction and minor losses are subtracted.",
    eq: "8.10", calc: null, fig: "8.4", table: null },
  { id: "8-028", ch: 8, sec: "8.2", page: 151, type: "figure", level: 2,
    q: "Per Figure 8.4, a pipeline rises and the outlet pressure P2 is known. How is the required inlet pressure P1 found?",
    opts: ["P1 = P2 − Pf − Pm + 0.433 × Rise", "P1 = P2 + Pf + Pm + 0.433 × Rise", "P1 = P2 + Pf + Pm − 0.433 × Rise", "P1 = P2 + Pf − Pm"], a: 1,
    why: "Working upstream you add back everything lost: friction, minor losses, and the pressure needed to lift water up the rise.",
    eq: "8.10", calc: null, fig: "8.4", table: null },
  { id: "8-029", ch: 8, sec: "8.2", page: 151, type: "figure", level: 2,
    q: "Using Figure 8.3, what is the velocity head for 1,000 gpm in a pipe with an 8-in inside diameter?",
    opts: ["About 0.63 ft", "About 0.38 ft", "About 0.13 ft", "About 1.0 ft"], a: 0,
    why: "The figure's worked example reads 0.63 ft at 1,000 gpm on the 8-in line. Computing: V = 6.38 ft/s, hv = 6.38²/64.4 = 0.63 ft. 0.38 ft is the 5 ft/s reference line.",
    eq: "8.1", calc: "eq-8.5", fig: "8.3", table: null },
  { id: "8-030", ch: 8, sec: "8.2", page: 149, type: "figure", level: 3,
    q: "In Figure 8.2(c), the pipe slopes downward from point 1 to point 2. Why is the pressure head h2 larger than h1 even though energy is lost to friction?",
    opts: ["Velocity increases downstream and adds pressure head", "Friction loss adds pressure at the downstream point", "The datum line is moved for point 2", "The drop in elevation head from z1 to z2 exceeds the friction loss, and the difference shows up as pressure head"], a: 3,
    why: "Hydraulic head (z + h) falls by the friction loss, but z falls by more, so h rises. This is the same effect as Example 8.5, where a 25-ft fall raised pressure.",
    eq: null, calc: null, fig: "8.2", table: null },
  { id: "8-031", ch: 8, sec: "8.2", page: 150, type: "concept", level: 3,
    q: "Example 8.2 has 15 ft of elevation, 60 psi, and 400 gpm in a 4-in pipe. Which component dominates the total head?",
    opts: ["Velocity head, about 1.6 of 156 ft", "Pressure head, about 139 of 156 ft", "Elevation head, about 15 of 156 ft", "All three are about equal"], a: 1,
    why: "h = 2.31 × 60 = 139 ft, Z = 15 ft, hv = 1.6 ft, so H = 156 ft. Pressure is the primary component, which is why velocity head is often ignored.",
    eq: "8.4", calc: "eq-8.4", fig: null, table: null },
  { id: "8-032", ch: 8, sec: "8.2", page: 150, type: "recall", level: 2,
    q: "In the examples, which conversion factor does the book use between gpm and cubic feet per second?",
    opts: ["7.48 gpm per cfs", "60 gpm per cfs", "450 gpm per cfs", "3,960 gpm per cfs"], a: 2,
    why: "Example 8.2 converts 400 gpm to 0.89 cfs using 450 gpm/cfs (exactly 448.8). 7.48 is gallons per cubic foot, and 3,960 appears in the water horsepower formula.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-033", ch: 8, sec: "8.3", page: 152, type: "recall", level: 1,
    q: "Which equation does the book use for friction loss in most surface and sprinkler irrigation pipelines?",
    opts: ["Darcy-Weisbach", "Manning", "Hazen-Williams", "Bernoulli"], a: 2,
    why: "Hazen-Williams (Eq. 8.11) applies to essentially all surface and sprinkler pipelines. Darcy-Weisbach is used for small microirrigation laterals in Chapter 14.",
    eq: "8.11a", calc: null, fig: null, table: null },
  { id: "8-034", ch: 8, sec: "8.3", page: 152, type: "recall", level: 2,
    q: "For small diameter pipes such as microirrigation laterals, which friction equation does the book say is more appropriate?",
    opts: ["Darcy-Weisbach", "Hazen-Williams with C = 150", "Manning with n = 0.009", "Scobey"], a: 0,
    why: "The book notes Darcy-Weisbach is more appropriate for small diameter laterals and applies it in Chapter 14.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-035", ch: 8, sec: "8.3", page: 152, type: "concept", level: 1,
    q: "What three things increase friction loss in a pipe?",
    opts: ["Larger diameter, smoother walls, and lower velocity", "Higher elevation, colder air, and fewer outlets", "Shorter pipe, more outlets, and lower flow", "Higher fluid viscosity, rougher pipe walls, and higher velocity"], a: 3,
    why: "The book lists the fluid (viscosity, like syrup vs water), the roughness of the conduit, and the velocity of flow.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-036", ch: 8, sec: "8.3", page: 152, type: "concept", level: 2,
    q: "How does the roughness coefficient C in Hazen-Williams relate to pipe roughness?",
    opts: ["C increases as the wall becomes rougher", "C decreases as the wall becomes rougher, so rough pipe has a lower C and more friction", "C does not depend on the pipe material", "C equals the inside diameter in inches"], a: 1,
    why: "Steel (C = 100) is the roughest and PVC (C = 150) the smoothest in Table 8.1. Friction loss varies with (1/C)^1.852.",
    eq: null, calc: null, fig: null, table: "8.1" },
  { id: "8-037", ch: 8, sec: "8.3", page: 152, type: "calc", level: 2,
    q: "Use Hazen-Williams (Eq. 8.11b) for 500 gpm in PVC pipe (C = 150) with a 5.766-in inside diameter and no outlets. What is the friction loss per 100 ft?",
    opts: ["0.84 psi/100 ft", "1.94 psi/100 ft", "0.36 psi/100 ft", "8.4 psi/100 ft"], a: 0,
    why: "Pf = 456 × (500/150)^1.852 × 5.766^−4.866 = 0.84 psi/100 ft, matching Table 8.2b for 6-in PVC PIP. 1.94 is the head loss in ft (2.31 × 0.84), not psi.",
    eq: "8.11b", calc: "eq-8.11", fig: null, table: null },
  { id: "8-038", ch: 8, sec: "8.3", page: 152, type: "calc", level: 3,
    q: "If the flow in a pipe doubles, by about what factor does Hazen-Williams friction loss increase?",
    opts: ["2.0", "3.6", "4.0", "8.0"], a: 1,
    why: "Friction varies with Q^1.852: 2^1.852 = 3.61. 4.0 would be a squared law, and 2.0 assumes proportionality.",
    eq: "8.11b", calc: "eq-8.11", fig: null, table: null },
  { id: "8-039", ch: 8, sec: "8.3", page: 152, type: "calc", level: 3,
    q: "A mainline is upsized from 6-in to 8-in inside diameter at the same flow. By about what fraction is friction loss reduced?",
    opts: ["To about 0.75 of the original", "To about 0.56 of the original", "To about 0.25 of the original", "To about 0.42 of the original"], a: 2,
    why: "Friction varies with d^−4.866: (6/8)^4.866 = 0.247. 0.75 is the diameter ratio and 0.56 its square. A modest size increase cuts friction sharply.",
    eq: "8.11b", calc: "eq-8.11", fig: null, table: null },
  { id: "8-040", ch: 8, sec: "8.3", page: 155, type: "calc", level: 2,
    q: "A 3-in aluminum lateral is 600 ft long with sprinklers every 40 ft, each discharging 6 gpm (15 sprinklers). Table 8.2a gives 1.51 psi/100 ft at 90 gpm, and F = 0.379. What is the friction loss along the lateral?",
    opts: ["9.1 psi", "1.3 psi", "0.57 psi", "3.4 psi"], a: 3,
    why: "Q = 15 × 6 = 90 gpm. Pf = F × (Pf/100) × L = 0.379 × 1.51 × 600/100 = 3.4 psi. 9.1 forgets the outlet factor, and 0.57 forgets to multiply by L/100.",
    eq: "8.11b", calc: "pipeline-design", fig: null, table: "8.3" },
  { id: "8-041", ch: 8, sec: "8.3", page: 155, type: "calc", level: 3,
    q: "The 3-in aluminum lateral above (600 ft, 90 gpm, 3.4 psi friction) rises 8 ft. With 50 psi at the inlet and minor losses ignored, what is the pressure at the end?",
    opts: ["46.6 psi", "43.1 psi", "28.1 psi", "50.1 psi"], a: 1,
    why: "P2 = P1 − Pf − 0.433 × Rise = 50 − 3.4 − 3.5 = 43.1 psi. 46.6 forgets the rise, 50.1 adds the rise as if it were a fall, and 28.1 uses 2.31 × 8 as psi.",
    eq: "8.10", calc: "pipeline-design", fig: null, table: null },
  { id: "8-042", ch: 8, sec: "8.3", page: 155, type: "concept", level: 2,
    q: "Why does a lateral with many outlets have less friction loss than a plain conveyance pipe carrying the same inlet flow over the same length?",
    opts: ["Outlets let air into the pipe, which lubricates the flow", "Laterals are always made of smoother pipe", "Flow, and so velocity, decreases along the lateral as water leaves through each outlet", "Outlets raise the pressure, which lowers friction"], a: 2,
    why: "Only the first segment carries the full flow. The outlet factor F (Table 8.3) accounts for the falling velocity, and F = 1.0 when there are no outlets.",
    eq: null, calc: null, fig: null, table: "8.3" },
  { id: "8-043", ch: 8, sec: "8.3", page: 155, type: "recall", level: 1,
    q: "What is the multiple outlet factor F for a pipeline with no outlets?",
    opts: ["0.36", "0.54", "0", "1.0"], a: 3,
    why: "With no outlets the full flow travels the whole length, so F = 1.0. Values below 1 apply to laterals with outlets.",
    eq: null, calc: null, fig: null, table: "8.3" },
  { id: "8-044", ch: 8, sec: "8.3", page: 155, type: "recall", level: 2,
    q: "Table 8.3 assumes a specific layout for the first outlet. What is it?",
    opts: ["The first outlet is one full spacing from the pipe inlet", "The first outlet is at the pipe inlet", "The first outlet is half a spacing from the inlet", "The first outlet is at the far end"], a: 0,
    why: "The caption states the first outlet is one full spacing from the inlet, with equally spaced outlets of the same discharge.",
    eq: null, calc: null, fig: null, table: "8.3" },
  { id: "8-045", ch: 8, sec: "8.3", page: 155, type: "concept", level: 3,
    q: "Why are center pivots given different outlet factors than the values in the body of Table 8.3?",
    opts: ["Pivots are made of PVC instead of aluminum", "Pivots have fewer than 10 outlets", "Pivot sprinkler discharge increases with distance from the pivot point, so the outlets do not have equal discharge", "Pivot pipes are not circular"], a: 2,
    why: "Table 8.3 assumes equal discharge per outlet. Pivot outlets near the end irrigate more area and discharge more, so F is 0.54 without and 0.56 with an end gun.",
    eq: null, calc: null, fig: null, table: "8.3" },
  { id: "8-046", ch: 8, sec: "8.3", page: 155, type: "recall", level: 2,
    q: "What causes minor losses in a pipeline?",
    opts: ["Friction along straight pipe walls", "Turbulence and changes in flow direction at fittings, valves, and other obstructions", "Leaks at pipe couplers", "Evaporation from open risers"], a: 1,
    why: "Minor losses occur at fittings and valves from friction in the fitting plus turbulence and direction changes. They are computed with hm = K × V²/2g (Eq. 8.12).",
    eq: "8.12", calc: null, fig: null, table: null },
  { id: "8-047", ch: 8, sec: "8.3", page: 155, type: "calc", level: 2,
    q: "500 gpm flows through a 6-in inside diameter pipe and a 90° regular flanged elbow (K = 0.28). What is the head loss in the elbow?",
    opts: ["0.14 ft", "0.50 ft", "0.06 ft", "1.59 ft"], a: 0,
    why: "V = 5.67 ft/s, hv = 5.67²/64.4 = 0.50 ft. hm = K × hv = 0.28 × 0.50 = 0.14 ft. 0.50 is just the velocity head, and 0.06 is the loss already converted to psi.",
    eq: "8.12", calc: "eq-8.12", fig: null, table: "8.4" },
  { id: "8-048", ch: 8, sec: "8.3", page: 155, type: "calc", level: 3,
    q: "250 gpm passes a 4-in flanged globe valve (K = 6.3) in a pipe with a 4-in inside diameter. What is the pressure loss across the valve?",
    opts: ["4.0 psi", "0.63 psi", "9.2 psi", "1.7 psi"], a: 3,
    why: "V = 6.38 ft/s, hv = 0.633 ft. hm = 6.3 × 0.633 = 3.99 ft. Pm = 0.433 × 3.99 = 1.7 psi. 4.0 is the head in ft, and 9.2 multiplies the head by 2.31.",
    eq: "8.12", calc: "eq-8.12", fig: null, table: "8.4" },
  { id: "8-049", ch: 8, sec: "8.3", page: 156, type: "concept", level: 3,
    q: "Why does a flanged globe valve cause far more loss than a flanged gate valve of the same size?",
    opts: ["It always carries more flow", "Its resistance coefficient K is about 30 to 90 times larger because flow turns sharply through the valve body", "It has a smaller nominal size", "Globe valves add friction from rubber seals only"], a: 1,
    why: "Table 8.4: globe flanged K = 5.5 to 7.0, gate flanged K = 0.06 to 0.21. Minor loss is proportional to K at a given velocity.",
    eq: "8.12", calc: null, fig: null, table: "8.4" },
  { id: "8-050", ch: 8, sec: "8.3", page: 152, type: "table", level: 1,
    q: "Per Table 8.1, what Hazen-Williams C value is used for PVC pipe?",
    opts: ["130", "120", "150", "140"], a: 2,
    why: "PVC is 150. PVC with gates is 130, aluminum with couplers 120, and cement asbestos and galvanized steel 140.",
    eq: null, calc: "tab-8.1", fig: null, table: "8.1" },
  { id: "8-051", ch: 8, sec: "8.3", page: 152, type: "table", level: 1,
    q: "Per Table 8.1, which pipe is the roughest?",
    opts: ["Standard steel pipe, C = 100", "Aluminum pipe with gates, C = 110", "Galvanized steel pipe, C = 140", "PVC pipe with gates, C = 130"], a: 0,
    why: "Lower C means rougher. Standard steel has the lowest C at 100.",
    eq: null, calc: "tab-8.1", fig: null, table: "8.1" },
  { id: "8-052", ch: 8, sec: "8.3", page: 153, type: "table", level: 2,
    q: "Per Table 8.2a, what is the friction loss for 120 gpm in 3-in aluminum sprinkler pipe, and is the velocity above 5 ft/s?",
    opts: ["2.57 psi/100 ft, not shaded, so below 5 ft/s", "0.61 psi/100 ft, not shaded", "1.01 psi/100 ft, shaded", "2.57 psi/100 ft, shaded, so above 5 ft/s"], a: 3,
    why: "The 3-in aluminum column reads 2.57 at 120 gpm in bold shading, meaning velocity exceeds 5 ft/s. 0.61 is the 4-in aluminum value and 1.01 the 3-in PVC value.",
    eq: null, calc: "tab-8.2", fig: null, table: "8.2a" },
  { id: "8-053", ch: 8, sec: "8.3", page: 153, type: "table", level: 2,
    q: "Per Table 8.2a, what is the friction loss for 200 gpm in 4-in PVC IPS Class 160 pipe?",
    opts: ["1.56 psi/100 ft", "2.59 psi/100 ft", "0.21 psi/100 ft", "0.76 psi/100 ft"], a: 3,
    why: "The PVC IPS 4-in column (4.150 in ID, C = 150) reads 0.76 at 200 gpm. 1.56 is 4-in aluminum, 2.59 is 3-in PVC, and 0.21 is 6-in aluminum.",
    eq: null, calc: "tab-8.2", fig: null, table: "8.2a" },
  { id: "8-054", ch: 8, sec: "8.3", page: 154, type: "table", level: 2,
    q: "Per Table 8.2b, what is the friction loss for 800 gpm in 8-in aluminum gated pipe?",
    opts: ["0.77 psi/100 ft", "0.51 psi/100 ft", "3.20 psi/100 ft", "0.26 psi/100 ft"], a: 0,
    why: "8-in aluminum gated (7.898 in ID, C = 110) reads 0.77 at 800 gpm. 0.51 is the 8-in PVC PIP value, 3.20 is 6-in gated, and 0.26 is 10-in gated.",
    eq: null, calc: "tab-8.2", fig: null, table: "8.2b" },
  { id: "8-055", ch: 8, sec: "8.3", page: 154, type: "table", level: 3,
    q: "Per Table 8.2b, 1,000 gpm in 10-in PVC PIP gives what friction loss, and what is the loss over 1,500 ft?",
    opts: ["0.39 psi/100 ft, 5.9 psi", "0.26 psi/100 ft, 3.9 psi", "0.76 psi/100 ft, 11.4 psi", "0.26 psi/100 ft, 0.39 psi"], a: 1,
    why: "10-in PVC PIP reads 0.26 at 1,000 gpm. Over 1,500 ft: 0.26 × 15 = 3.9 psi. 0.39 is the 10-in aluminum gated value, and 0.39 psi forgets L/100.",
    eq: null, calc: "tab-8.2", fig: null, table: "8.2b" },
  { id: "8-056", ch: 8, sec: "8.3", page: 155, type: "table", level: 1,
    q: "Per Table 8.3, what is the multiple outlet factor for a lateral with 10 equally spaced outlets?",
    opts: ["0.362", "0.433", "0.396", "0.355"], a: 2,
    why: "Table 8.3: 10 outlets, F = 0.396. 0.362 is 30 outlets, 0.433 is 6, and 0.355 is 50.",
    eq: null, calc: "tab-8.3", fig: null, table: "8.3" },
  { id: "8-057", ch: 8, sec: "8.3", page: 155, type: "table", level: 1,
    q: "Per Table 8.3, what outlet factor is used for a center pivot with an end gun?",
    opts: ["0.54", "0.56", "0.345", "1.0"], a: 1,
    why: "The footnote gives F = 0.56 with an end gun and 0.54 without. 0.345 is for more than 100 equal outlets on a lateral.",
    eq: null, calc: "tab-8.3", fig: null, table: "8.3" },
  { id: "8-058", ch: 8, sec: "8.3", page: 156, type: "table", level: 1,
    q: "Per Table 8.4, what is K for a flanged swing check valve?",
    opts: ["2.0 at all listed sizes", "0.80 at all listed sizes", "6.3 for 4-in", "0.16 for 4-in"], a: 0,
    why: "Swing check flanged is 2.0 from 3 to 10 in. 0.80 is the foot valve, 6.3 the 4-in flanged globe valve, and 0.16 the 4-in flanged gate valve.",
    eq: null, calc: "tab-8.4", fig: null, table: "8.4" },
  { id: "8-059", ch: 8, sec: "8.3", page: 156, type: "table", level: 2,
    q: "Per Table 8.4, what is K for a 6-in basket type strainer?",
    opts: ["1.25", "0.60", "0.28", "0.85"], a: 3,
    why: "Strainers (basket type) at 6 in: 0.85. 1.25 is the 3-in strainer, 0.60 the 6-in flanged tee branch flow, and 0.28 the 6-in regular flanged elbow.",
    eq: null, calc: "tab-8.4", fig: null, table: "8.4" },
  { id: "8-060", ch: 8, sec: "8.3", page: 156, type: "table", level: 3,
    q: "Per Table 8.4, an 8-in line has one flanged swing check valve (K = 2.0) and two long radius flanged 90° elbows. What is the total K?",
    opts: ["2.52", "2.15", "2.30", "4.30"], a: 2,
    why: "Long radius flanged 90° at 8 in is 0.15, so ΣK = 2.0 + 2 × 0.15 = 2.30. 2.52 uses the regular flanged elbow (0.26), and 2.15 counts only one elbow.",
    eq: null, calc: "eq-8.12", fig: null, table: "8.4" },
  { id: "8-061", ch: 8, sec: "8.4", page: 156, type: "recall", level: 1,
    q: "What pipe material is common for center pivot and linear move systems?",
    opts: ["PVC", "Galvanized steel", "Polyethylene", "Cement asbestos"], a: 1,
    why: "The book notes pivots and laterals are the exception to aluminum and PVC, commonly using galvanized steel.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-062", ch: 8, sec: "8.4", page: 156, type: "recall", level: 1,
    q: "What material is most common for aboveground microirrigation laterals?",
    opts: ["Aluminum", "Galvanized steel", "Polyethylene (PE)", "PVC with gates"], a: 2,
    why: "Aboveground micro laterals are usually PE. Buried agricultural pipelines are most commonly PVC, and buried micro lines PE.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-063", ch: 8, sec: "8.4", page: 156, type: "recall", level: 2,
    q: "Per the book, mainline pipe sizing is usually based on what average velocity?",
    opts: ["A maximum of 5 to 6 ft/s", "A minimum of 10 ft/s", "Exactly 2 ft/s", "Whatever velocity gives zero friction"], a: 0,
    why: "Mainlines are sized for a maximum of 5 to 6 ft/s. Table 8.5 lists flows at 5 ft/s.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-064", ch: 8, sec: "8.4", page: 156, type: "table", level: 1,
    q: "Per Table 8.5, what is the maximum flow for 10-in aluminum gated pipe at 5 ft/s?",
    opts: ["1,120 gpm", "765 gpm", "1,615 gpm", "1,200 gpm"], a: 3,
    why: "10-in aluminum gated (9.898 in ID) carries 1,200 gpm at 5 ft/s. 1,120 is 10-in PVC PIP, 765 is 8-in gated, and 1,615 is 12-in PVC PIP.",
    eq: null, calc: "tab-8.5", fig: null, table: "8.5" },
  { id: "8-065", ch: 8, sec: "8.4", page: 156, type: "table", level: 2,
    q: "Per Table 8.5, which is the smallest PVC PIP size that keeps 1,000 gpm at or below 5 ft/s?",
    opts: ["8 in", "12 in", "6 in", "10 in"], a: 3,
    why: "8-in PVC PIP tops out at 720 gpm, and 10-in at 1,120 gpm. 1,000 gpm therefore needs the 10-in.",
    eq: null, calc: "tab-8.5", fig: null, table: "8.5" },
  { id: "8-066", ch: 8, sec: "8.4", page: 156, type: "table", level: 1,
    q: "Per Table 8.5, what flow does 4-in PVC IPS pipe carry at 5 ft/s?",
    opts: ["185 gpm", "210 gpm", "130 gpm", "460 gpm"], a: 1,
    why: "PVC IPS 4-in: 210 gpm. 185 is 4-in aluminum sprinkler pipe, 130 is 3-in PVC IPS, and 460 is 6-in PVC IPS.",
    eq: null, calc: "tab-8.5", fig: null, table: "8.5" },
  { id: "8-067", ch: 8, sec: "8.4", page: 157, type: "calc", level: 3,
    q: "A 10-in PVC PIP mainline carries 1,000 gpm for 1,500 ft and rises 15 ft. Table 8.2b gives 0.26 psi/100 ft. Inlet pressure is 70 psi. What is the pressure at the end (ignore minor losses)?",
    opts: ["66.1 psi", "72.6 psi", "59.6 psi", "31.4 psi"], a: 2,
    why: "P2 = 70 − 0.26 × 15 − 0.433 × 15 = 70 − 3.9 − 6.5 = 59.6 psi. 66.1 forgets the rise, 72.6 adds the rise as a fall, and 31.4 uses 2.31 × 15.",
    eq: "8.10", calc: "pipeline-design", fig: null, table: "8.2b" },
  { id: "8-068", ch: 8, sec: "8.4", page: 157, type: "calc", level: 3,
    q: "A PVC PIP mainline carries 700 gpm, is 600 ft long, falls 25 ft, and starts at 35 psi. Using 8-in pipe (0.39 psi/100 ft), what is the outlet pressure?",
    opts: ["43.5 psi", "21.8 psi", "32.7 psi", "90.4 psi"], a: 0,
    why: "P2 = 35 − 0.39 × 6 + 0.433 × 25 = 35 − 2.34 + 10.8 = 43.5 psi. The fall raises pressure. 21.8 treats the fall as a rise, and 90.4 uses 2.31 × 25 as psi.",
    eq: "8.10", calc: "pipeline-design", fig: null, table: "8.2b" },
  { id: "8-069", ch: 8, sec: "8.4", page: 157, type: "recall", level: 2,
    q: "Where does the book say combination vacuum and air vent relief valves should be placed on a buried pipeline?",
    opts: ["Only at the pump discharge", "At the pipeline entrance, at high points, at the end, and at about 1,000-ft intervals", "Only at low points", "Every 100 ft regardless of profile"], a: 1,
    why: "Air must escape during filling and vacuum must be relieved on draining. The book lists the entrance, high points, the end, and 1,000-ft intervals.",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-070", ch: 8, sec: "8.4", page: 157, type: "recall", level: 2,
    q: "Where should pressure relief valves be installed on an irrigation pipeline?",
    opts: ["At the inlet and at dead ends", "Only at high points", "At every sprinkler riser", "Only downstream of the check valve at low points"], a: 0,
    why: "Pressure relief valves protect against surges and belong at the inlet and dead ends (Figures 8.5 and 8.6).",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-071", ch: 8, sec: "8.4", page: 157, type: "concept", level: 2,
    q: "Why is a check valve suggested at the inlet of a pipeline?",
    opts: ["To reduce friction loss in the mainline", "To release trapped air at startup", "To prevent reverse flow when the pumping system stops", "To meter the flow rate"], a: 2,
    why: "Without a check valve, water in the line can drain back through the pump when it shuts off. Backflow prevention equipment is also required with chemigation or municipal connections.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-072", ch: 8, sec: "8.4", page: 157, type: "concept", level: 2,
    q: "Why must air be relieved at high points in a pipeline?",
    opts: ["Air at high points raises the C value", "Air relief lowers the elevation head", "Air at high points prevents water hammer", "Trapped air can block flow and gets compressed during filling"], a: 3,
    why: "Air collects at high points, and an air pocket can block flow. Air must also not be compressed while the line fills.",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-073", ch: 8, sec: "8.4", page: 157, type: "figure", level: 1,
    q: "In Figure 8.5, which valve is placed at low points of a buried pipeline?",
    opts: ["Automatic drain valve (D)", "Vacuum air vent valve (VA)", "Pressure relief valve (PR)", "Check valve (C)"], a: 0,
    why: "Low points get the automatic drain valve so the line can be emptied, for example to prevent freeze damage. VA valves go at high points and 1,000-ft intervals.",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-074", ch: 8, sec: "8.4", page: 157, type: "figure", level: 2,
    q: "In Figure 8.5, which valves are shown at the end of the pipeline?",
    opts: ["A check valve and a shutoff valve", "A vacuum air vent valve and a pressure relief valve", "Only an automatic drain valve", "A shutoff valve and a drain valve"], a: 1,
    why: "The end shows VA and PR. The pump end has VA, check valve, shutoff valve, and PR in sequence.",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-075", ch: 8, sec: "8.4", page: 157, type: "concept", level: 2,
    q: "What protection does the book require for pipelines buried shallower than the frost depth?",
    opts: ["A pressure relief valve every 100 ft", "Insulation wrap on every coupler", "Running the pump all winter", "Drainage so freezing water does not burst the pipe"], a: 3,
    why: "Water left in a shallow line can freeze and burst it. Providing drainage (automatic drain valves at low points) prevents this.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-076", ch: 8, sec: "8.5", page: 158, type: "recall", level: 1,
    q: "Which pumps are most commonly used for irrigation wells?",
    opts: ["Horizontal centrifugal pumps", "Piston pumps", "Vertical turbine and submersible pumps", "Diaphragm pumps"], a: 2,
    why: "Submersible and vertical turbine pumps are the most common in wells. Horizontal centrifugal pumps are used at open water sources and as boosters.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-077", ch: 8, sec: "8.5", page: 158, type: "recall", level: 2,
    q: "How does a submersible pump differ from a vertical turbine pump?",
    opts: ["Both pump and electric motor are submersed, with the motor below the pump", "The motor is above ground and drives a vertical shaft", "It has a horizontal shaft at the water surface", "It can only be driven by a diesel engine"], a: 0,
    why: "The vertical turbine has its power source above ground on a vertical shaft. The submersible places both pump and motor in the water, motor below.",
    eq: null, calc: null, fig: "8.8", table: null },
  { id: "8-078", ch: 8, sec: "8.5", page: 159, type: "recall", level: 1,
    q: "What is total dynamic head (TDH)?",
    opts: ["The pressure at the sprinkler nozzle", "The depth to static water in the well", "The friction loss in the mainline", "The total head produced by the pump at a given flow rate"], a: 3,
    why: "TDH is the head the pump adds at a given flow, approximated by 2.31 P + L for a well (Eq. 8.13).",
    eq: "8.13", calc: null, fig: null, table: null },
  { id: "8-079", ch: 8, sec: "8.5", page: 159, type: "calc", level: 1,
    q: "A well pump lifts water 120 ft and discharges at 60 psi. What is the TDH?",
    opts: ["180 ft", "146 ft", "259 ft", "73 ft"], a: 2,
    why: "Eq. 8.13: TDH = 2.31 × 60 + 120 = 138.6 + 120 = 258.6 ft. 180 adds psi directly to feet, and 146 uses 0.433 × 60.",
    eq: "8.13", calc: "eq-8.13", fig: null, table: null },
  { id: "8-080", ch: 8, sec: "8.5", page: 159, type: "calc", level: 1,
    q: "A booster pump takes water in at 20 psi and discharges at 65 psi. What TDH does it develop?",
    opts: ["196 ft", "104 ft", "45 ft", "150 ft"], a: 1,
    why: "Eq. 8.14: TDH = 2.31 × (65 − 20) = 104 ft. 196 adds the pressures, and 45 is psi, not ft.",
    eq: "8.14", calc: "eq-8.14", fig: null, table: null },
  { id: "8-081", ch: 8, sec: "8.5", page: 159, type: "concept", level: 2,
    q: "Why is Eq. 8.13 (TDH = 2.31 P + L) only an approximation?",
    opts: ["It ignores velocity head and the friction and minor losses in moving water up to the surface", "It assumes the pump is 100% efficient", "It applies only to booster pumps", "It ignores the discharge pressure"], a: 0,
    why: "The book notes we ignore velocity head plus friction and minor losses in the column. It is adequate for many but not all pumping conditions.",
    eq: "8.13", calc: null, fig: null, table: null },
  { id: "8-082", ch: 8, sec: "8.5", page: 159, type: "concept", level: 1,
    q: "On a centrifugal pump, what happens to flow as a valve downstream is gradually closed?",
    opts: ["Flow and pressure both decrease", "Flow stays the same and pressure rises", "Flow increases because velocity rises", "Flow decreases and the pressure (TDH) upstream of the valve rises"], a: 3,
    why: "A centrifugal pump follows its head-capacity curve: more TDH means less flow. Closing a valve raises the head and moves the pump left on the curve.",
    eq: null, calc: null, fig: "8.9", table: null },
  { id: "8-083", ch: 8, sec: "8.5", page: 159, type: "recall", level: 2,
    q: "What range of peak efficiencies does the book give for pump sizes commonly used in irrigation?",
    opts: ["30 to 50%", "85 to 95%", "55 to 82%", "70 to 75% only"], a: 2,
    why: "Peak efficiencies range from about 55 to 82%. The Nebraska criteria assume 75%.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-084", ch: 8, sec: "8.5", page: 160, type: "figure", level: 1,
    q: "Per Figure 8.9, at about what flow and head does the pump reach peak efficiency?",
    opts: ["About 500 gpm at 220 ft", "About 1,100 gpm at 190 ft", "About 1,500 gpm at 120 ft", "About 1,750 gpm at 90 ft"], a: 1,
    why: "The efficiency curve peaks near 80% at about 1,100 gpm, where the head-capacity curve reads about 190 ft. Efficiency falls on either side.",
    eq: null, calc: null, fig: "8.9", table: null },
  { id: "8-085", ch: 8, sec: "8.5", page: 160, type: "figure", level: 2,
    q: "Per Figure 8.9, about what is the shutoff head (head at zero flow)?",
    opts: ["About 190 ft", "About 228 ft", "About 250 ft", "About 90 ft"], a: 1,
    why: "The head-capacity curve starts at about 228 ft at zero flow. 190 ft is the head at peak efficiency, and 90 ft is near the end of the curve at 1,750 gpm.",
    eq: null, calc: null, fig: "8.9", table: null },
  { id: "8-086", ch: 8, sec: "8.5", page: 160, type: "figure", level: 2,
    q: "Per Figure 8.10, what is the shutoff head per stage at 1,460 rpm?",
    opts: ["50.2 ft", "22.5 ft", "34.5 ft", "41.4 ft"], a: 2,
    why: "The figure lists shutoff heads of 50.2 ft at 1,760 rpm, 34.5 ft at 1,460 rpm, and 22.5 ft at 1,160 rpm.",
    eq: null, calc: null, fig: "8.10", table: null },
  { id: "8-087", ch: 8, sec: "8.5", page: 160, type: "figure", level: 3,
    q: "Figure 8.10 gives a shutoff head of 50.2 ft at 1,760 rpm. What does the affinity law predict for 1,460 rpm, and does it match the figure?",
    opts: ["41.6 ft, which is higher than the figure", "28.7 ft, which is lower than the figure", "50.2 ft, because shutoff head does not change with speed", "34.5 ft, which matches the figure"], a: 3,
    why: "TDH2 = 50.2 × (1,460/1,760)² = 34.5 ft, the same as listed. 41.6 uses a linear ratio, and 28.7 uses the cube.",
    eq: "8.15a", calc: "eq-8.15", fig: "8.10", table: null },
  { id: "8-088", ch: 8, sec: "8.5", page: 160, type: "concept", level: 2,
    q: "Per Figure 8.10, as pump speed is reduced, what happens to the point of peak efficiency?",
    opts: ["It shifts to a lower flow rate", "It shifts to a higher flow rate", "It stays at the same flow rate", "It disappears"], a: 0,
    why: "The book notes the peak efficiency point moves left (lower flow) at lower speed. Impeller trimming does the same (Figure 8.11).",
    eq: null, calc: null, fig: "8.10", table: null },
  { id: "8-089", ch: 8, sec: "8.5", page: 161, type: "figure", level: 1,
    q: "Per Figure 8.11 (12SKL at 1,770 rpm), what head per stage does the 8.19-in impeller produce at 800 gpm?",
    opts: ["About 47 ft", "About 57 ft", "About 84 ft", "About 37 ft"], a: 1,
    why: "The 8.19-in curve crosses 800 gpm at about 57 ft, the value used in Example 8.11. 47 ft is the 7.75-in curve, and 84 ft is the 8.19-in shutoff head.",
    eq: null, calc: null, fig: "8.11", table: null },
  { id: "8-090", ch: 8, sec: "8.5", page: 161, type: "figure", level: 2,
    q: "Per Figure 8.11, which impeller diameter gives about 47 ft per stage at 800 gpm?",
    opts: ["8.19 in", "7.25 in", "6.75 in", "7.75 in"], a: 3,
    why: "The 7.75-in curve passes about 47 ft at 800 gpm. Example 8.11 picks this trim to produce 235 ft with 5 stages.",
    eq: null, calc: null, fig: "8.11", table: null },
  { id: "8-091", ch: 8, sec: "8.5", page: 161, type: "figure", level: 3,
    q: "Per Figure 8.11, what is the highest efficiency marked for the 12SKL pump, and on which curve?",
    opts: ["80%, on the 6.75-in curve near 650 gpm", "72%, on the 8.19-in curve near 1,100 gpm", "81.7%, on the 8.19-in curve near 850 gpm", "77%, on the 7.25-in curve near 600 gpm"], a: 2,
    why: "The efficiency contours peak at 81.7% on the 8.19-in curve between about 840 and 860 gpm. Efficiency at 1,100 gpm drops to about 72%.",
    eq: null, calc: null, fig: "8.11", table: null },
  { id: "8-092", ch: 8, sec: "8.5", page: 161, type: "figure", level: 3,
    q: "Per Figure 8.11, about how much power per stage does the 8.19-in impeller draw near 800 gpm?",
    opts: ["About 14 hp", "About 7 hp", "About 10 hp", "About 57 hp"], a: 0,
    why: "The top power curve (8.19 in) is near 14 hp per stage around 800 to 900 gpm. Smaller trims draw about 7 to 12 hp. 57 is head in ft, not hp.",
    eq: null, calc: null, fig: "8.11", table: null },
  { id: "8-093", ch: 8, sec: "8.5", page: 162, type: "calc", level: 3,
    q: "A well pump must deliver 800 gpm against a 180-ft lift and 55 psi discharge pressure. Each stage gives 45 ft at 800 gpm. How many stages are needed?",
    opts: ["6 stages", "5 stages", "7 stages", "4 stages"], a: 2,
    why: "TDH = 2.31 × 55 + 180 = 307 ft. 307/45 = 6.8, so round up to 7 stages. 6 stages gives only 270 ft, which falls short.",
    eq: "8.13", calc: "eq-8.13", fig: null, table: null },
  { id: "8-094", ch: 8, sec: "8.5", page: 162, type: "concept", level: 2,
    q: "How do pumps in series combine?",
    opts: ["Their flows add at the same head", "The same flow passes through each pump and their heads add", "Both head and flow add", "The higher head pump sets the head and the flows add"], a: 1,
    why: "Series (and multistage) operation adds TDH at a common flow, as shown by HA + HB on the combined curve in Figure 8.12.",
    eq: null, calc: null, fig: "8.12", table: null },
  { id: "8-095", ch: 8, sec: "8.5", page: 162, type: "figure", level: 2,
    q: "In Figure 8.12, what does the combined curve represent?",
    opts: ["The sum of the flows of pumps A and B at each head", "The average of the two pump curves", "The system head curve", "The sum of the heads of pumps A and B at each flow rate"], a: 3,
    why: "For pumps in series, each flow passes through both pumps, so the combined head at a given Q is HA + HB.",
    eq: null, calc: null, fig: "8.12", table: null },
  { id: "8-096", ch: 8, sec: "8.5", page: 162, type: "concept", level: 2,
    q: "When is operating pumps in parallel especially useful?",
    opts: ["When system flow demand varies greatly", "When more head is needed at the same flow", "When the water source is very deep", "When the pipeline is very long and steep"], a: 0,
    why: "Parallel pumps share the same discharge head and their flows add, so one or both can run to meet a variable demand. Series is for more head.",
    eq: null, calc: null, fig: "8.13", table: null },
  { id: "8-097", ch: 8, sec: "8.5", page: 162, type: "figure", level: 2,
    q: "In Figure 8.13, how is the combined curve for pumps A and B in parallel built?",
    opts: ["By adding HA and HB at the same flow", "By taking the higher of the two heads", "By averaging the two flows", "By adding QA and QB at the same total dynamic head"], a: 3,
    why: "In parallel the pressure downstream is the same for both pumps (Figure 8.14), so the total flow is QA + QB at that common TDH.",
    eq: null, calc: null, fig: "8.13", table: null },
  { id: "8-098", ch: 8, sec: "8.5", page: 163, type: "recall", level: 2,
    q: "In the affinity laws, how do flow, TDH, and brake horsepower vary with pump speed?",
    opts: ["Flow with speed squared, TDH with speed, BHP with speed cubed", "All three vary in direct proportion to speed", "Flow with speed, TDH with speed squared, BHP with speed cubed", "Flow with speed cubed, TDH with speed squared, BHP with speed"], a: 2,
    why: "Eq. 8.15a: Q2/Q1 = N2/N1, TDH2/TDH1 = (N2/N1)², BHP2/BHP1 = (N2/N1)³. The same exponents apply to impeller diameter (Eq. 8.15b).",
    eq: "8.15a", calc: "eq-8.15", fig: null, table: null },
  { id: "8-099", ch: 8, sec: "8.5", page: 163, type: "calc", level: 1,
    q: "A pump delivers 600 gpm at 1,760 rpm. What flow does the affinity law predict at 1,460 rpm?",
    opts: ["498 gpm", "413 gpm", "343 gpm", "723 gpm"], a: 0,
    why: "Q2 = 600 × 1,460/1,760 = 498 gpm. 413 uses the square of the speed ratio (that is for TDH), and 723 inverts the ratio.",
    eq: "8.15a", calc: "eq-8.15", fig: null, table: null },
  { id: "8-100", ch: 8, sec: "8.5", page: 163, type: "calc", level: 3,
    q: "An impeller is trimmed from 8.19 in to 7.75 in. If the pump drew 14 bhp per stage before, what does the affinity law predict after?",
    opts: ["13.2 bhp", "11.9 bhp", "12.5 bhp", "16.5 bhp"], a: 1,
    why: "BHP2 = 14 × (7.75/8.19)³ = 14 × 0.847 = 11.9 bhp. 13.2 uses a linear ratio, 12.5 the square, and 16.5 inverts the ratio.",
    eq: "8.15b", calc: "eq-8.15", fig: null, table: null },
  { id: "8-101", ch: 8, sec: "8.5", page: 163, type: "calc", level: 3,
    q: "A pump produces 50 ft per stage at 1,760 rpm at its operating point. To what speed should a VFD slow it to produce 40 ft per stage, by the affinity laws?",
    opts: ["About 1,408 rpm", "About 1,634 rpm", "About 1,574 rpm", "About 1,126 rpm"], a: 2,
    why: "TDH ∝ N², so N2 = 1,760 × √(40/50) = 1,760 × 0.894 = 1,574 rpm. 1,408 uses a linear ratio, and 1,634 uses the cube root.",
    eq: "8.15a", calc: "eq-8.15", fig: null, table: null },
  { id: "8-102", ch: 8, sec: "8.5", page: 163, type: "concept", level: 2,
    q: "Why does the book warn against oversizing a pump and throttling it with a valve?",
    opts: ["Throttling valves increase the flow above design", "Oversized pumps cannot be started by electric motors", "Throttling lowers the water horsepower to zero", "The valve burns off excess head, so the pump uses more energy than the system needs"], a: 3,
    why: "Excess head produced by the pump is dissipated across the valve. Example 8.11 shows 21% more energy than needed because of this.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-103", ch: 8, sec: "8.5", page: 162, type: "concept", level: 1,
    q: "What is a multistage pump?",
    opts: ["A pump with several bowl and impeller assemblies in series, each adding head at the same flow", "Several pumps in parallel feeding one pipe", "A pump with a variable speed drive", "A pump used for both lift and booster duty"], a: 0,
    why: "Vertical turbine and submersible pumps stack stages. Four stages of 54 ft give 216 ft at the same flow.",
    eq: null, calc: null, fig: "8.8", table: null },
  { id: "8-104", ch: 8, sec: "8.6", page: 163, type: "recall", level: 1,
    q: "How is one horsepower defined in USCS units?",
    opts: ["3,960 ft-lb/min", "33,000 ft-lb/min", "550 ft-lb/min", "746 ft-lb/s"], a: 1,
    why: "1 hp = 33,000 ft-lb/min (Eq. 8.17), which equals 550 ft-lb/s. 3,960 is gallons lifted 1 ft per minute by 1 hp.",
    eq: "8.17", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-105", ch: 8, sec: "8.6", page: 164, type: "concept", level: 2,
    q: "Where does the constant 3,960 in the water horsepower equation come from?",
    opts: ["It is 450 gpm/cfs times 8.8", "It is 62.4 lb/ft³ times 63.5", "It is 2.31 ft/psi times 1,714", "33,000 ft-lb/min divided by 8.33 lb/gal gives about 3,960 gal lifted 1 ft per minute per hp"], a: 3,
    why: "A gallon weighs 8.33 lb, so 1 hp lifts 33,000/8.33 = 3,960 gallons 1 ft per minute. Hence whp = Q × TDH/3,960.",
    eq: "8.18", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-106", ch: 8, sec: "8.6", page: 164, type: "calc", level: 1,
    q: "A pump delivers 1,000 gpm at a TDH of 250 ft. What is the water horsepower?",
    opts: ["63 whp", "84 whp", "16 whp", "250 whp"], a: 0,
    why: "Eq. 8.18: whp = 1,000 × 250/3,960 = 63.1 whp. 84 is the brake horsepower at 75% efficiency.",
    eq: "8.18", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-107", ch: 8, sec: "8.6", page: 164, type: "calc", level: 2,
    q: "A pump lifts water 150 ft and discharges at 40 psi with 600 gpm. Pump efficiency is 78%. What brake horsepower is required?",
    opts: ["37 bhp", "47 bhp", "29 bhp", "60 bhp"], a: 1,
    why: "TDH = 2.31 × 40 + 150 = 242 ft. whp = 600 × 242/3,960 = 36.7. bhp = 36.7/0.78 = 47 bhp. 37 is the water horsepower, and 29 multiplies by 0.78.",
    eq: "8.19", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-108", ch: 8, sec: "8.6", page: 163, type: "calc", level: 1,
    q: "A test shows a pump delivering 40 whp while drawing 55 hp at the shaft. What is the pump efficiency?",
    opts: ["138%", "27%", "73%", "15%"], a: 2,
    why: "Eq. 8.16: Ep = output/input = 40/55 = 0.727, or 73%. 138% inverts the ratio, and 27% is the loss.",
    eq: "8.16", calc: "eq-8.16", fig: null, table: null },
  { id: "8-109", ch: 8, sec: "8.6", page: 164, type: "concept", level: 1,
    q: "What is the difference between water horsepower and brake horsepower?",
    opts: ["They are always equal", "Brake horsepower is the power lost in friction in the pipeline", "Water horsepower includes motor losses, brake horsepower does not", "Water horsepower is the power actually added to the water, brake horsepower is the power input to the pump shaft"], a: 3,
    why: "bhp = whp/Ep, so brake horsepower is always larger because the pump is not 100% efficient.",
    eq: "8.19", calc: null, fig: null, table: null },
  { id: "8-110", ch: 8, sec: "8.6", page: 164, type: "calc", level: 3,
    q: "A 12SKL pump must deliver 750 gpm against 34 ft of lift and 40 psi. If it runs at 80% efficiency, what is the smallest standard motor from 10, 15, 20, 25, 30, 40, and 50 hp that covers the brake horsepower?",
    opts: ["25 hp", "30 hp", "20 hp", "40 hp"], a: 1,
    why: "TDH = 2.31 × 40 + 34 = 126.4 ft. whp = 750 × 126.4/3,960 = 23.9. bhp = 23.9/0.80 = 29.9, so a 30 hp motor. 25 hp covers only the water horsepower.",
    eq: "8.19", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-111", ch: 8, sec: "8.7", page: 165, type: "recall", level: 1,
    q: "What is the Nebraska Pumping Plant Performance Criterion for electric pumping plants?",
    opts: ["12.5 whp-hr per kWh", "1.34 whp-hr per kWh", "0.885 whp-hr per kWh", "0.75 whp-hr per kWh"], a: 2,
    why: "Table 8.6 lists 0.885 whp-hr/kWh for electricity. 12.5 is diesel per gallon, and 1.34 hp equals 1 kW.",
    eq: null, calc: "tab-8.6", fig: null, table: "8.6" },
  { id: "8-112", ch: 8, sec: "8.7", page: 165, type: "recall", level: 2,
    q: "In building the electric criterion, what motor and pump efficiencies does the Nebraska method assume?",
    opts: ["Motor 88%, pump 75%, direct drive 100%", "Motor 95%, pump 82%, drive 95%", "Motor 75%, pump 88%, drive 100%", "Motor 83%, pump 55%, drive 95%"], a: 0,
    why: "1 kW = 1.34 hp × 0.88 (motor) × 1.00 (direct drive) × 0.75 (pump) = 0.885 whp.",
    eq: null, calc: null, fig: null, table: "8.6" },
  { id: "8-113", ch: 8, sec: "8.7", page: 165, type: "recall", level: 2,
    q: "What drive efficiency does the Nebraska criteria assume for internal combustion engines, and why?",
    opts: ["100%, because engines connect directly", "88%, because engines lose heat", "75%, the same as the pump", "95%, because belt or right-angle gear drives are used"], a: 3,
    why: "Engines usually drive through a right-angle gear or belt, losing about 5% to heat, so drive efficiency is 95%. Electric motors are assumed direct connected at 100%.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-114", ch: 8, sec: "8.7", page: 165, type: "recall", level: 2,
    q: "What is the typical fully loaded efficiency range for electric motors from 5 to 250 hp?",
    opts: ["55 to 82%", "95 to 99%", "83 to 94%", "60 to 75%"], a: 2,
    why: "The book gives 83 to 94% for motors. 55 to 82% is the range for pump peak efficiency.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-115", ch: 8, sec: "8.7", page: 165, type: "table", level: 1,
    q: "Per Table 8.6, what is the performance criterion for a propane powered pumping plant?",
    opts: ["8.66 whp-hr per gallon", "6.89 whp-hr per gallon", "12.5 whp-hr per gallon", "61.7 whp-hr per gallon"], a: 1,
    why: "Propane is 6.89. Gasoline is 8.66, diesel 12.5 (all per gallon), and natural gas 61.7 per mcf.",
    eq: null, calc: "tab-8.6", fig: null, table: "8.6" },
  { id: "8-116", ch: 8, sec: "8.7", page: 165, type: "table", level: 2,
    q: "Per Table 8.6, what is the energy unit and criterion for natural gas?",
    opts: ["61.7 whp-hr per 1,000 ft³ (mcf)", "61.7 whp-hr per therm", "6.89 whp-hr per mcf", "925 whp-hr per mcf"], a: 0,
    why: "Natural gas is 61.7 whp-hr per mcf, with the footnote basing it on a natural gas energy content of 925 btu/mcf. 925 is that energy content, not the criterion.",
    eq: null, calc: "tab-8.6", fig: null, table: "8.6" },
  { id: "8-117", ch: 8, sec: "8.7", page: 165, type: "concept", level: 2,
    q: "What does a performance rating (PR) of 0.80 mean?",
    opts: ["The pump is 80% efficient", "The pumping plant uses 80% of the energy the criteria expect", "The pumping plant produces 80% of the water horsepower-hours per unit of energy that the Nebraska criteria expect", "The motor is 80% loaded"], a: 2,
    why: "PR = actual performance / criteria (Eq. 8.20). At 0.80 the plant uses 1/0.80 = 1.25 times the energy of a plant meeting the criteria.",
    eq: "8.20", calc: "eq-8.20", fig: null, table: null },
  { id: "8-118", ch: 8, sec: "8.7", page: 166, type: "calc", level: 3,
    q: "A diesel pumping plant delivers 1,000 gpm at a TDH of 230 ft and burns 6 gal/hr. What is its performance rating?",
    opts: ["1.29", "0.97", "0.58", "0.77"], a: 3,
    why: "whp = 1,000 × 230/3,960 = 58.1. Actual performance = 58.1/6 = 9.68 whp-hr/gal. PR = 9.68/12.5 = 0.77. 1.29 inverts the ratio.",
    eq: "8.20", calc: "eq-8.20", fig: null, table: null },
  { id: "8-119", ch: 8, sec: "8.7", page: 166, type: "calc", level: 2,
    q: "An electric pumping plant produces 50 whp while drawing 70 kW. What is its performance rating?",
    opts: ["0.71", "0.81", "1.24", "0.63"], a: 1,
    why: "Actual = 50/70 = 0.714 whp-hr/kWh. PR = 0.714/0.885 = 0.81. 0.71 stops at actual performance, and 0.63 multiplies by 0.885.",
    eq: "8.20", calc: "eq-8.20", fig: null, table: null },
  { id: "8-120", ch: 8, sec: "8.7", page: 166, type: "calc", level: 2,
    q: "An electric pumping plant produces 44 whp and has a performance rating of 0.80. How many kW does it draw?",
    opts: ["62 kW", "50 kW", "31 kW", "39 kW"], a: 0,
    why: "Eq. 8.21: Energy/hr = whp/(PC × PR) = 44/(0.885 × 0.80) = 62 kWh per hour, which is 62 kW. 50 assumes PR = 1, and 31 multiplies instead of dividing.",
    eq: "8.21", calc: "eq-8.21", fig: null, table: null },
  { id: "8-121", ch: 8, sec: "8.7", page: 166, type: "calc", level: 1,
    q: "A diesel pumping plant produces 44 whp and meets the Nebraska criteria exactly. How much fuel does it use per hour?",
    opts: ["550 gal/hr", "3.5 gal/hr", "4.0 gal/hr", "0.28 gal/hr"], a: 1,
    why: "Energy/hr = 44/(12.5 × 1.0) = 3.52 gal/hr. 550 multiplies by 12.5, and 4.0 is the Example 8.7 measured rate at PR 0.88.",
    eq: "8.21", calc: "eq-8.21", fig: null, table: null },
  { id: "8-122", ch: 8, sec: "8.7", page: 167, type: "calc", level: 2,
    q: "An electric pump runs at a TDH of 216 ft and meets the criteria (PR = 1). How much energy does it use per acre-inch pumped?",
    opts: ["24.7 kWh/ac-in", "1.97 kWh/ac-in", "27.9 kWh/ac-in", "21.8 kWh/ac-in"], a: 2,
    why: "Eq. 8.22: E = TDH/(8.75 × PC × PR) = 216/(8.75 × 0.885 × 1) = 27.9 kWh/ac-in. 24.7 divides by 8.75 only, 21.8 multiplies by 0.885, and 1.97 is the diesel value in gal/ac-in.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-123", ch: 8, sec: "8.7", page: 167, type: "calc", level: 3,
    q: "A natural gas pumping plant runs at a TDH of 300 ft with a performance rating of 0.70. How much gas does it use per acre-inch?",
    opts: ["0.79 mcf/ac-in", "0.56 mcf/ac-in", "4.97 mcf/ac-in", "1.42 mcf/ac-in"], a: 0,
    why: "E = 300/(8.75 × 61.7 × 0.70) = 0.79 mcf/ac-in. 0.56 ignores the performance rating (uses PR = 1), and 4.97 uses the propane criterion 6.89 with PR 1.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-124", ch: 8, sec: "8.7", page: 167, type: "calc", level: 3,
    q: "A diesel plant runs at TDH 250 ft with PR 0.85 and pumps 400 ac-in a season. Diesel costs $3.50/gal. What is the season fuel cost?",
    opts: ["About $3,200", "About $940", "About $11,760", "About $3,760"], a: 3,
    why: "E = 250/(8.75 × 12.5 × 0.85) = 2.69 gal/ac-in. Season fuel = 2.69 × 400 = 1,076 gal. Cost = 1,076 × 3.50 = $3,760. $3,200 assumes PR = 1, and $940 covers only 100 ac-in.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-125", ch: 8, sec: "8.7", page: 167, type: "concept", level: 2,
    q: "Improving a diesel pumping plant from PR 0.88 to PR 1.0 reduces fuel per acre-inch by about how much?",
    opts: ["About 12%", "About 50%", "About 1%", "About 88%"], a: 0,
    why: "Energy per ac-in is inversely proportional to PR: 2.24 vs 1.97 gal/ac-in, a drop of 0.27/2.24 = 12%. The book rounds this to about 10%.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-126", ch: 8, sec: "8.7", page: 168, type: "calc", level: 3,
    q: "A sprinkler system needs 45 psi and the lift is 120 ft at design flow. The installed pump has 4 stages producing 70 ft each. How much excess head must a throttling valve burn?",
    opts: ["56 ft (about 129 psi)", "56 ft (about 24 psi)", "104 ft (about 45 psi)", "160 ft (about 69 psi)"], a: 1,
    why: "Design TDH = 2.31 × 45 + 120 = 224 ft. Pump produces 4 × 70 = 280 ft. Excess = 56 ft, or 56/2.31 = 24 psi. 129 psi multiplies by 2.31 instead of dividing.",
    eq: "8.13", calc: "pump-match", fig: null, table: null },
  { id: "8-127", ch: 8, sec: "8.7", page: 168, type: "calc", level: 3,
    q: "A pump is throttled so it produces 280 ft of TDH when the system needs only 224 ft. At the same PR and energy source, how much extra energy per acre-inch does it use?",
    opts: ["About 20% more", "About 56% more", "About 25% more", "No extra, the valve recovers the energy"], a: 2,
    why: "Eq. 8.22 makes energy per ac-in proportional to TDH: 280/224 = 1.25, or 25% more. 20% is the excess as a share of 280 instead of 224.",
    eq: "8.22", calc: "pump-match", fig: null, table: null },
  { id: "8-128", ch: 8, sec: "8.7", page: 168, type: "calc", level: 2,
    q: "Example 8.11 needs 800 gpm at 40 psi with a 143-ft lift. Using the electric criterion and PR = 1, what is the energy per acre-inch at the design TDH?",
    opts: ["36.8 kWh/ac-in", "26.8 kWh/ac-in", "18.5 kWh/ac-in", "30.3 kWh/ac-in"], a: 3,
    why: "TDH = 2.31 × 40 + 143 = 235 ft. E = 235/(8.75 × 0.885 × 1) = 30.3 kWh/ac-in. 36.8 is the throttled value at 285 ft, and 26.8 leaves out the 0.885 criterion.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-129", ch: 8, sec: "8.7", page: 168, type: "concept", level: 3,
    q: "What is the difference between pump discharge pressure and system pressure?",
    opts: ["They are the same reading", "System pressure is always higher than discharge pressure", "Discharge pressure includes the lift, system pressure does not", "Discharge pressure is measured right at the pump outlet, system pressure is the pressure actually entering the irrigation system or mainline"], a: 3,
    why: "With a throttling valve, for instance, the pump may discharge at 62 psi while the system receives 40 psi. TDH uses pump discharge pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-130", ch: 8, sec: "8.7", page: 168, type: "concept", level: 2,
    q: "What alternative to changing an oversized impeller does the book suggest?",
    opts: ["Adding a second pump in series", "A variable frequency drive (VFD) on the electric motor to lower pump speed", "Installing a larger check valve", "Raising the system pressure"], a: 1,
    why: "A VFD controls motor speed to hold the desired pressure. By the affinity laws, slowing the pump reduces head and power.",
    eq: null, calc: null, fig: "8.16", table: null },
  { id: "8-131", ch: 8, sec: "8.7", page: 168, type: "recall", level: 2,
    q: "Which measurement does the book call probably the most difficult when evaluating a pumping plant?",
    opts: ["Discharge pressure", "Flow rate", "Pumping lift", "Fuel use"], a: 2,
    why: "Pumping lift is hardest to measure. A permanently installed air line on the well is a useful addition (USGS, 2010).",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-132", ch: 8, sec: "8.7", page: 168, type: "recall", level: 1,
    q: "Besides correcting pump mismatch, the book says VFDs are especially useful where pumping conditions change with time. Which example does it give?",
    opts: ["Variable rate irrigation or a center pivot with a corner arm", "A gravity-fed furrow system", "A pipeline with a single fixed outlet", "Hand-move laterals at constant pressure"], a: 0,
    why: "When demand changes, as with VRI or a corner arm extending and retracting, a VFD adjusts pump speed to match.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-133", ch: 8, sec: "8.7", page: 166, type: "concept", level: 3,
    q: "How can a manager estimate a pumping plant's performance rating from annual records without measuring fuel rate?",
    opts: ["Use Eq. 8.22 with the TDH, the season volume pumped, and the season energy used", "Divide the fuel used by the hours run", "Divide the TDH by 3,960", "Compare the motor nameplate with the pump curve"], a: 0,
    why: "Energy per ac-in = season energy/season volume. Rearranging Eq. 8.22 gives PR = TDH/(8.75 × PC × E).",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-134", ch: 8, sec: "8.7", page: 166, type: "calc", level: 3,
    q: "A diesel center pivot well records 3,900 gal of fuel for 1,300 ac-in pumped. Lift is 150 ft and discharge pressure 50 psi. What is the performance rating?",
    opts: ["0.65", "1.24", "0.97", "0.81"], a: 3,
    why: "TDH = 2.31 × 50 + 150 = 265.5 ft. Actual E = 3,900/1,300 = 3.0 gal/ac-in. PR = 265.5/(8.75 × 12.5 × 3.0) = 0.81. 1.24 inverts the ratio, and 0.65 uses TDH = 2.31 × 50 + 100.",
    eq: "8.22", calc: "pump-eval", fig: null, table: null },
  { id: "8-135", ch: 8, sec: "8.8", page: 169, type: "recall", level: 1,
    q: "Per the chapter summary, pipes are sized based on economics and what other consideration emphasized in the chapter?",
    opts: ["Keeping the pipe color consistent", "Limiting water velocities within reasonable limits", "Matching the crop's root depth", "Minimizing the number of outlets"], a: 1,
    why: "The summary says pipes are sized on economics and limiting velocities, the latter being the focus of this chapter (about 5 ft/s).",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-136", ch: 8, sec: "8.2", page: 151, type: "scenario", level: 2,
    q: "\"My mountain reservoir sits 240 ft above the valley. The pipeline loses 40 psi to friction and fittings. My sprinklers need 60 psi. Do I need a pump?\" What do you tell the grower?",
    opts: ["Yes, gravity gives only 64 psi before losses, leaving 24 psi", "Yes, 240 ft is only 40 psi", "No, gravity gives about 104 psi, leaving about 64 psi after losses", "No, gravity gives 554 psi"], a: 2,
    why: "Pressure from elevation = 0.433 × 240 = 104 psi. After 40 psi of losses, about 64 psi remains, above 60 psi. 554 uses 2.31 × 240.",
    eq: "8.10", calc: "eq-8.10", fig: null, table: null },
  { id: "8-137", ch: 8, sec: "8.4", page: 157, type: "scenario", level: 3,
    q: "\"My 10-in aluminum gated pipe carries 1,000 gpm. The last set starts 900 ft from the well and 9 ft higher. The well discharges at 10 psi.\" Using 0.39 psi/100 ft from Table 8.2b, what pressure reaches the last set?",
    opts: ["About 6.1 psi", "About 2.6 psi", "About 6.5 psi", "About negative 14 psi"], a: 1,
    why: "P2 = 10 − 0.39 × 9 − 0.433 × 9 = 10 − 3.5 − 3.9 = 2.6 psi. 6.5 forgets the rise, 6.1 forgets friction, and a negative value uses 2.31 × 9 as psi.",
    eq: "8.10", calc: "pipeline-design", fig: null, table: "8.2b" },
  { id: "8-138", ch: 8, sec: "8.2", page: 148, type: "scenario", level: 1,
    q: "\"I stuck a clear tube in my last gate and held it up. The gauge there reads 4 psi. How high should water stand in the tube?\" What is the answer?",
    opts: ["About 1.7 ft", "About 4 ft", "About 9.2 ft", "About 33 ft"], a: 2,
    why: "h = 2.31 × 4 = 9.24 ft. 1.7 ft uses 0.433 × 4, which converts the wrong way.",
    eq: "8.2", calc: "eq-8.2-8.3", fig: null, table: null },
  { id: "8-139", ch: 8, sec: "8.3", page: 155, type: "scenario", level: 2,
    q: "\"My hand-move lateral loses pressure toward the end. I want to estimate friction loss, but the table is for plain pipe.\" What do you tell the grower?",
    opts: ["Use the plain pipe loss for the inlet flow, then multiply by the outlet factor F from Table 8.3 for the number of sprinklers", "Use the plain pipe loss as is, outlets do not matter", "Divide the plain pipe loss by the number of sprinklers", "Double the plain pipe loss to cover outlet turbulence"], a: 0,
    why: "Pf = F × (Pf/100 ft) × L, with Pf/100 ft taken at the inlet flow. F is about 0.36 for 30 or more outlets, so actual loss is roughly a third of plain pipe loss.",
    eq: null, calc: "pipeline-design", fig: null, table: "8.3" },
  { id: "8-140", ch: 8, sec: "8.4", page: 156, type: "scenario", level: 2,
    q: "\"I'm laying a new PVC PIP mainline for a 700 gpm drip system. What size do I need?\" What do you recommend?",
    opts: ["6 in, which carries up to 700 gpm at 5 ft/s", "10 in, since 8 in tops out at 405 gpm", "4 in, which carries 1,120 gpm", "8 in, which carries up to 720 gpm at 5 ft/s"], a: 3,
    why: "Table 8.5: 6-in PVC PIP holds 405 gpm and 8-in holds 720 gpm at 5 ft/s, so 8 in is the smallest that keeps velocity at or below 5 ft/s.",
    eq: null, calc: "tab-8.5", fig: null, table: "8.5" },
  { id: "8-141", ch: 8, sec: "8.4", page: 157, type: "scenario", level: 3,
    q: "\"My buried mainline goes over a ridge, and some mornings the flow chokes down until I open a valve at the top.\" What is the likely cause and fix?",
    opts: ["The pipe has too much friction, so add a booster pump", "The check valve is installed backward", "Air is collecting at the high point, so install a combination vacuum and air vent relief valve there", "Frost has frozen the line, so bury it deeper"], a: 2,
    why: "Air gathers at high points and blocks flow. Figure 8.5 places VA valves at high points and at about 1,000-ft intervals.",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-142", ch: 8, sec: "8.4", page: 157, type: "scenario", level: 2,
    q: "\"We plan to inject fertilizer through our well-fed pivot.\" What pipeline protection must be in place?",
    opts: ["Only an air vent at the pivot point", "Proper backflow prevention equipment so chemicals cannot flow back into the well", "A pressure relief valve at the end of the pivot", "A larger strainer at the pump"], a: 1,
    why: "The book requires backflow prevention for chemigation and municipal connections (Chapter 15). A check valve alone is not considered adequate protection.",
    eq: null, calc: null, fig: null, table: null },
  { id: "8-143", ch: 8, sec: "8.5", page: 160, type: "scenario", level: 2,
    q: "\"My centrifugal pump puts out less water than when it was new, and the discharge gauge reads higher than before.\" What does that tell you first?",
    opts: ["The pump speed has increased", "The well has more water than before", "The pressure gauge must be broken because head and flow always rise together", "The pump is working against more head, so look downstream for a restriction such as a partly closed valve or clogged screen"], a: 3,
    why: "On a head-capacity curve, higher TDH means lower flow. A restriction raises the head the pump sees and slides it to lower flow.",
    eq: null, calc: null, fig: "8.9", table: null },
  { id: "8-144", ch: 8, sec: "8.5", page: 162, type: "scenario", level: 3,
    q: "\"My demand swings between 750 and 1,300 gpm depending on which fields are on.\" What pump arrangement fits best?",
    opts: ["Two pumps in parallel, running one or both, so flows add at the same system head", "Two pumps in series, so heads add at the same flow", "One large pump throttled with a valve at low demand", "One small pump run at a higher speed during peaks"], a: 0,
    why: "Parallel operation suits highly variable demand. Throttling one large pump wastes energy, and series operation adds head, not flow.",
    eq: null, calc: null, fig: "8.13", table: null },
  { id: "8-145", ch: 8, sec: "8.5", page: 162, type: "scenario", level: 2,
    q: "\"The dealer has a pump that's efficient at my 800 gpm, but it only makes 54 ft of head per bowl. I need 216 ft.\" What do you tell the grower?",
    opts: ["Use a multistage pump with 4 stages in series", "Use 4 pumps in parallel", "It cannot work, pick a different pump", "Use 2 stages and raise the speed by 50%"], a: 0,
    why: "Stages in series add head at the same flow: 4 × 54 = 216 ft. Parallel pumps add flow, not head.",
    eq: null, calc: "eq-8.13", fig: null, table: null },
  { id: "8-146", ch: 8, sec: "8.7", page: 168, type: "scenario", level: 3,
    q: "\"My pump makes 62 psi at the discharge but the gauge past the valve reads 40 psi, which is what the sprinklers need. Is that a problem?\" What do you tell the grower?",
    opts: ["No, the extra pressure is stored in the pipeline for later", "No, as long as the sprinklers get 40 psi there is no cost", "Yes, the valve is burning about 50 ft of head, so trim the impeller or add a VFD to save around 20% energy", "Yes, the sprinklers need 62 psi, so open the valve fully"], a: 2,
    why: "22 psi × 2.31 = 51 ft of head lost in the throttling valve. In Example 8.11 that wasted 21% more energy than a properly matched pump.",
    eq: null, calc: "pump-match", fig: null, table: null },
  { id: "8-147", ch: 8, sec: "8.7", page: 166, type: "scenario", level: 2,
    q: "\"How do I know if my diesel pumping plant is any good?\" What do you need to measure?",
    opts: ["Only the engine hours", "Lift, discharge pressure, flow rate, and fuel use per hour, then compare with the Nebraska criteria", "Only the discharge pressure", "Only the fuel price"], a: 1,
    why: "With lift and pressure you get TDH, with flow you get whp, and with fuel rate you get actual whp-hr/gal. Dividing by 12.5 gives the performance rating.",
    eq: null, calc: "pump-eval", fig: null, table: null },
  { id: "8-148", ch: 8, sec: "8.7", page: 166, type: "scenario", level: 3,
    q: "\"My diesel plant tests at a performance rating of 0.75 and burns 4.7 gal/hr. How much would I save per hour if it met the criteria?\" What is the answer?",
    opts: ["About 3.5 gal/hr", "About 0.75 gal/hr", "About 4.7 gal/hr", "About 1.2 gal/hr"], a: 3,
    why: "Fuel use is inversely proportional to PR. At PR = 1: 4.7 × 0.75 = 3.5 gal/hr, saving 1.2 gal/hr. 3.5 gal/hr is the new fuel rate, not the saving.",
    eq: "8.21", calc: "eq-8.21", fig: null, table: null },
  { id: "8-149", ch: 8, sec: "8.6", page: 164, type: "scenario", level: 2,
    q: "\"I need 1,000 gpm at 250 ft of TDH, and the pump is 75% efficient. What size motor do I need?\" What do you tell the grower?",
    opts: ["At least about 84 hp at the shaft, so the next standard size above that", "63 hp, the water horsepower", "47 hp, the water horsepower times the efficiency", "250 hp, one per foot of head"], a: 0,
    why: "whp = 1,000 × 250/3,960 = 63.1. bhp = 63.1/0.75 = 84. The motor must cover brake horsepower, not water horsepower.",
    eq: "8.19", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "8-150", ch: 8, sec: "8.7", page: 168, type: "scenario", level: 2,
    q: "\"My pump was installed with the wrong impeller and makes too much pressure. Pulling it to trim the impeller is expensive.\" What is the alternative?",
    opts: ["Leave it and throttle the valve, it costs nothing", "Add a second pump in parallel", "Put a variable frequency drive on the motor to run the pump at the speed that delivers the needed pressure", "Raise the sprinkler nozzle size to use up the pressure"], a: 2,
    why: "A VFD slows the pump. In Example 8.11, about 1,670 rpm instead of 1,770 rpm holds 40 psi without the throttling loss.",
    eq: null, calc: null, fig: "8.16", table: null },
  { id: "8-151", ch: 8, sec: "8.7", page: 166, type: "scenario", level: 3,
    q: "\"Last year my diesel well pumped 1,300 ac-in and used 3,900 gallons. TDH is about 265 ft. If I got it to PR 1.0, how much fuel would I use?\" What is the answer?",
    opts: ["About 3,900 gal", "About 3,150 gal", "About 4,820 gal", "About 2,420 gal"], a: 1,
    why: "At PR = 1: E = 265.5/(8.75 × 12.5) = 2.43 gal/ac-in. 2.43 × 1,300 = 3,155 gal, about 3,150 gal, saving about 750 gal. 4,820 divides instead of multiplying by the current PR of 0.81.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "8-152", ch: 8, sec: "8.2", page: 151, type: "scenario", level: 2,
    q: "\"My drip block is 40 ft lower than the filter station. Why is the pressure at the block higher than at the filters?\" What do you explain?",
    opts: ["Friction adds pressure along the pipe", "Water speeds up downhill and the velocity head becomes pressure", "The gauge at the block must read high", "Each foot of fall adds 0.433 psi, so a 40-ft drop adds about 17 psi, more than the friction loss"], a: 3,
    why: "Going downhill, elevation head converts to pressure: 0.433 × 40 = 17.3 psi. If friction is less than that, pressure rises (Figure 8.4).",
    eq: "8.10", calc: null, fig: "8.4", table: null },
  { id: "8-153", ch: 8, sec: "8.3", page: 156, type: "scenario", level: 3,
    q: "\"I'm adding a filter station with several valves and elbows to my mainline. Are those fittings worth worrying about?\" What is the best answer?",
    opts: ["No, fittings never matter in irrigation", "Only if the pipe is longer than a mile", "Yes, sum the K values from Table 8.4 and compute hm = ΣK × V²/2g, since items like globe valves (K about 6) can cost several psi", "Only elbows matter, valves add no loss"], a: 2,
    why: "Minor loss scales with K and velocity head. A single 4-in globe valve at 250 gpm loses about 1.7 psi, so a cluster of fittings adds up.",
    eq: "8.12", calc: "eq-8.12", fig: null, table: "8.4" },
  { id: "8-154", ch: 8, sec: "8.5", page: 163, type: "scenario", level: 3,
    q: "\"If I slow my pump 10% with a VFD, how much power do I save?\" What does the affinity law say?",
    opts: ["Power drops 10%, with no change in head", "Power drops to 81%, and flow stays the same", "Power stays the same because the motor is the same size", "Power drops to about 73% (0.9³), but flow drops to 90% and head to 81%, so check the system still gets enough pressure"], a: 3,
    why: "BHP ∝ N³: 0.9³ = 0.73. Flow ∝ N (0.90) and TDH ∝ N² (0.81). The savings are real only if the reduced head still meets the system's needs.",
    eq: "8.15a", calc: "eq-8.15", fig: null, table: null },
  { id: "8-155", ch: 8, sec: "8.4", page: 157, type: "scenario", level: 1,
    q: "\"When my well pump shuts off, I hear water rushing back down the column.\" What valve is missing or failing?",
    opts: ["The check valve at the pipeline inlet", "The air vent at the end of the line", "The automatic drain at the low point", "The pressure relief at the dead end"], a: 0,
    why: "A check valve at the inlet prevents reverse flow when the pump stops (Figure 8.5).",
    eq: null, calc: null, fig: "8.5", table: null },
  { id: "8-156", ch: 8, sec: "8.2", page: 147, type: "scenario", level: 2,
    q: "\"I want to push 300 gpm through my existing 4-in line instead of 200 gpm.\" What concern do you raise first?",
    opts: ["Flow cannot exceed 200 gpm in any 4-in pipe", "Velocity would be about 7.7 ft/s, above the 5 ft/s guideline, raising water hammer risk and friction loss", "Velocity would drop and sediment would settle", "Pressure would rise at the outlet"], a: 1,
    why: "V = 0.668 cfs / 0.0873 ft² = 7.7 ft/s. Above 5 ft/s, sudden valve closure can cause damaging surges, and friction rises with Q^1.852.",
    eq: "8.5", calc: "eq-8.5", fig: null, table: null },
  { id: "8-157", ch: 8, sec: "8.7", page: 165, type: "scenario", level: 3,
    q: "\"Which is cheaper to pump with, electricity or diesel?\" What should you compare?",
    opts: ["Only the horsepower of each power unit", "Energy cost per acre-inch from Eq. 8.22 using each source's criterion, PR, and local price", "Only the price per gallon versus price per kWh", "The pump curve for each power unit"], a: 1,
    why: "E = TDH/(8.75 × PC × PR) gives fuel or kWh per ac-in for each source. Multiply by the local unit price to compare dollars per ac-in on equal footing.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: "8.6" },
  { id: "8-158", ch: 8, sec: "8.3", page: 153, type: "scenario", level: 3,
    q: "\"My 3-in aluminum lateral feeds 120 gpm. Is it sized right?\" What do you tell the grower from Table 8.2a?",
    opts: ["It is fine: 0.61 psi/100 ft is low", "It is oversized: drop to 2-in pipe", "It is undersized: 120 gpm is in the shaded zone above 5 ft/s with 2.57 psi/100 ft, so a 4-in line (0.61 psi/100 ft) is better", "It is fine as long as the lateral is level"], a: 2,
    why: "Table 8.2a shows 2.57 psi/100 ft in bold shading for 3-in aluminum at 120 gpm, meaning velocity over 5 ft/s. The 4-in line loses 0.61 psi/100 ft and is not shaded.",
    eq: null, calc: "tab-8.2", fig: null, table: "8.2a" },
  { id: "8-159", ch: 8, sec: "8.6", page: 164, type: "scenario", level: 1,
    q: "\"My pump lifts 100 ft and makes 50 psi at 800 gpm. What TDH should I give the pump dealer?\" What is the answer?",
    opts: ["About 150 ft", "About 122 ft", "About 316 ft", "About 216 ft"], a: 3,
    why: "TDH = 2.31 × 50 + 100 = 215.5 ft, about 216 ft. 150 adds psi to feet, and 122 uses 0.433 × 50.",
    eq: "8.13", calc: "eq-8.13", fig: null, table: null },
  { id: "8-160", ch: 8, sec: "8.7", page: 166, type: "concept", level: 2,
    q: "Why does the book call accurate, maintained pressure gauges a must on an irrigation system?",
    opts: ["They are needed both to compute TDH for energy management and to check that flow and pressure still agree with the design", "They are required by law on every pivot", "They reduce friction loss in the mainline", "They replace the need for a flow meter"], a: 0,
    why: "TDH needs lift and pump discharge pressure, and a gauge also tells you whether the system is operating as designed. Flow still has to be measured separately (Chapter 3).",
    eq: null, calc: null, fig: null, table: null }
]);
